import { eq, useLiveQuery } from '@tanstack/vue-db'
import { fromLiveQuery } from '#layers/core/app/data/results'
import { postsCollection } from '../../data/posts.collection'

/** Query "Featured posts": published posts, newest first, at most `limit`. `data`, `status` and `error` are refs, `refresh()` refetches the Posts. */
export const useFeaturedPosts = (limit = 6) => {
  const query = useLiveQuery(q => q
    .from({ post: postsCollection })
    .where(({ post }) => eq(post.published, true))
    .orderBy(({ post }) => post.publishedAt, 'desc')
    .limit(limit)
  )
  return fromLiveQuery(query, () => postsCollection.utils.refetch())
}
